// bdx-wire-fixtures.json is matter.js's own encoding of every BDX message,
// the BDX StatusReport, payloads its decoders refuse and OTA images its
// OtaImageWriter writes — generated by
// notes/parity/matter/generate-bdx-wire-fixtures.ts.
//
//go:embed testdata/bdx-wire-fixtures.json
var fixturesJSON []byte

type hexBytes struct {
	Hex string `json:"hex"`
}

func (h *hexBytes) bytes(t *testing.T) []byte {
	t.Helper()
	if h == nil {
		return nil
	}
	b, err := hex.DecodeString(h.Hex)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// jsNumber is a fixture number: a JSON number, or a bigint rendered as
// "<digits>n".
type jsNumber struct {
	v    uint64
	wide bool
}

func (n *jsNumber) UnmarshalJSON(b []byte) error {
	s := string(b)
	if strings.HasPrefix(s, `"`) {
		s = strings.TrimSuffix(strings.Trim(s, `"`), "n")
		n.wide = true
	}
	v, err := strconv.ParseUint(s, 10, 64)
	n.v = v
	return err
}

type tcJSON struct {
	Version              uint8 `json:"version"`
	SenderDrive          bool  `json:"senderDrive"`
	ReceiverDrive        bool  `json:"receiverDrive"`
	AsynchronousTransfer bool  `json:"asynchronousTransfer"`
}

func (c tcJSON) tc() bdx.TransferControl {
	return bdx.TransferControl{Version: c.Version, SenderDrive: c.SenderDrive, ReceiverDrive: c.ReceiverDrive, AsynchronousTransfer: c.AsynchronousTransfer}
}

type messageJSON struct {
	TransferProtocol *tcJSON   `json:"transferProtocol"`
	TransferControl  *tcJSON   `json:"transferControl"`
	MaxBlockSize     uint16    `json:"maxBlockSize"`
	StartOffset      *jsNumber `json:"startOffset"`
	MaxLength        *jsNumber `json:"maxLength"`
	Length           *jsNumber `json:"length"`
	FileDesignator   *hexBytes `json:"fileDesignator"`
	MetaData         *hexBytes `json:"metaData"`
	BlockCounter     uint32    `json:"blockCounter"`
	BytesToSkip      *jsNumber `json:"bytesToSkip"`
	Data             *hexBytes `json:"data"`
}

type fixtures struct {
	Messages []struct {
		Label    string      `json:"label"`
		Kind     uint8       `json:"kind"`
		Message  messageJSON `json:"message"`
		Decoded  messageJSON `json:"decoded"`
		BytesHex string      `json:"bytesHex"`
	} `json:"messages"`
	StatusReports []struct {
		GeneralStatus  uint16 `json:"generalStatus"`
		ProtocolStatus uint16 `json:"protocolStatus"`
		BytesHex       string `json:"bytesHex"`
	} `json:"statusReports"`
	Refused []struct {
		Label    string `json:"label"`
		Kind     uint8  `json:"kind"`
		BytesHex string `json:"bytesHex"`
		Code     uint16 `json:"code"`
	} `json:"refused"`
	Images []struct {
		Label  string `json:"label"`
		Header struct {
			VendorID                     uint16    `json:"vendorId"`
			ProductID                    uint16    `json:"productId"`
			SoftwareVersion              uint32    `json:"softwareVersion"`
			SoftwareVersionString        string    `json:"softwareVersionString"`
			PayloadSize                  uint64    `json:"payloadSize"`
			MinApplicableSoftwareVersion *uint32   `json:"minApplicableSoftwareVersion"`
			MaxApplicableSoftwareVersion *uint32   `json:"maxApplicableSoftwareVersion"`
			ReleaseNotesURL              *string   `json:"releaseNotesUrl"`
			ImageDigestType              uint8     `json:"imageDigestType"`
			ImageDigest                  *hexBytes `json:"imageDigest"`
		} `json:"header"`
		ImageHex string `json:"imageHex"`
	} `json:"images"`
}

func loadFixtures(t *testing.T) fixtures {
	t.Helper()
	var f fixtures
	if err := json.Unmarshal(fixturesJSON, &f); err != nil {
		t.Fatal(err)
	}
	if len(f.Messages) == 0 || len(f.StatusReports) == 0 || len(f.Refused) == 0 || len(f.Images) == 0 {
		t.Fatal("fixture file incomplete")
	}
	return f
}

func ptr(n *jsNumber) (*uint64, bool) {
	if n == nil {
		return nil, false
	}
	v := n.v
	return &v, n.wide
}

// goMessage builds the Go form of a fixture message.
func goMessage(t *testing.T, kind bdx.MessageType, m messageJSON) interface{ encode() ([]byte, error) } {
	t.Helper()
	switch kind {
	case bdx.MessageSendInit, bdx.MessageReceiveInit:
		off, wideOff := ptr(m.StartOffset)
		ml, wideLen := ptr(m.MaxLength)
		return encFn(func() ([]byte, error) {
			return bdx.Init{
				TransferControl: m.TransferProtocol.tc(), MaxBlockSize: m.MaxBlockSize,
				StartOffset: off, MaxLength: ml, WideRange: wideOff || wideLen,
				FileDesignator: m.FileDesignator.bytes(t), MetaData: m.MetaData.bytes(t),
			}.Encode()
		})
	case bdx.MessageSendAccept:
		return encFn(func() ([]byte, error) {
			return bdx.SendAccept{TransferControl: m.TransferControl.tc(), MaxBlockSize: m.MaxBlockSize, MetaData: m.MetaData.bytes(t)}.Encode()
		})
	case bdx.MessageReceiveAccept:
		l, wide := ptr(m.Length)
		return encFn(func() ([]byte, error) {
			return bdx.ReceiveAccept{TransferControl: m.TransferControl.tc(), MaxBlockSize: m.MaxBlockSize, Length: l, WideRange: wide, MetaData: m.MetaData.bytes(t)}.Encode()
		})
	case bdx.MessageBlock, bdx.MessageBlockEOF:
		return encFn(func() ([]byte, error) {
			return bdx.Block{BlockCounter: m.BlockCounter, Data: m.Data.bytes(t)}.Encode(), nil
		})
	case bdx.MessageBlockQuery, bdx.MessageBlockAck, bdx.MessageBlockAckEOF:
		return encFn(func() ([]byte, error) { return bdx.CounterOnly{BlockCounter: m.BlockCounter}.Encode(), nil })
	case bdx.MessageBlockQueryWithSkip:
		return encFn(func() ([]byte, error) {
			return bdx.BlockQueryWithSkip{BlockCounter: m.BlockCounter, BytesToSkip: m.BytesToSkip.v}.Encode(), nil
		})
	}
	t.Fatalf("unknown kind %d", kind)
	return nil
}

type encFn func() ([]byte, error)

func (f encFn) encode() ([]byte, error) { return f() }

// TestBdxMessagesParityMatterJS: every BDX message encodes to matter.js's
// bytes (BdxMessage.encode), and decodes back to what matter.js decodes
// (BdxMessage.decode) — the zero length of an indefinite *Init dropped as
// matter.js drops it (BdxInitMessagesSchema.ts:130, :164-166).
func TestBdxMessagesParityMatterJS(t *testing.T) {
	t.Parallel()
	for _, fx := range loadFixtures(t).Messages {
		t.Run(fx.Label, func(t *testing.T) {
			t.Parallel()
			kind := bdx.MessageType(fx.Kind)
			want, _ := hex.DecodeString(fx.BytesHex)
			got, err := goMessage(t, kind, fx.Message).encode()
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, want) {
				t.Fatalf("encode = %x, matter.js %x", got, want)
			}
			decoded, err := bdx.Decode(kind, want)
			if err != nil {
				t.Fatal(err)
			}
			// Re-encoding the decoded form gives the same bytes, and the
			// decoded form is what matter.js decoded.
			again, err := goMessage(t, kind, fx.Decoded).encode()
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(again, want) {
				t.Fatalf("decoded fixture re-encodes to %x, want %x", again, want)
			}
			checkDecoded(t, kind, decoded, fx.Decoded)
		})
	}
}

func checkDecoded(t *testing.T, kind bdx.MessageType, decoded any, want messageJSON) {
	t.Helper()
	eq := func(a *uint64, b *jsNumber) bool {
		if a == nil || b == nil {
			return a == nil && b == nil
		}
		return *a == b.v
	}
	switch v := decoded.(type) {
	case bdx.Init:
		if v.TransferControl != want.TransferProtocol.tc() || v.MaxBlockSize != want.MaxBlockSize ||
			!eq(v.StartOffset, want.StartOffset) || !eq(v.MaxLength, want.MaxLength) ||
			!bytes.Equal(v.FileDesignator, want.FileDesignator.bytes(t)) || !bytes.Equal(v.MetaData, want.MetaData.bytes(t)) {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	case bdx.SendAccept:
		if v.TransferControl != want.TransferControl.tc() || v.MaxBlockSize != want.MaxBlockSize || !bytes.Equal(v.MetaData, want.MetaData.bytes(t)) {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	case bdx.ReceiveAccept:
		if v.TransferControl != want.TransferControl.tc() || v.MaxBlockSize != want.MaxBlockSize ||
			!eq(v.Length, want.Length) || !bytes.Equal(v.MetaData, want.MetaData.bytes(t)) {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	case bdx.Block:
		if v.BlockCounter != want.BlockCounter || !bytes.Equal(v.Data, want.Data.bytes(t)) {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	case bdx.CounterOnly:
		if v.BlockCounter != want.BlockCounter {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	case bdx.BlockQueryWithSkip:
		if v.BlockCounter != want.BlockCounter || v.BytesToSkip != want.BytesToSkip.v {
			t.Fatalf("%s decoded %+v, matter.js %+v", kind, v, want)
		}
	default:
		t.Fatalf("decoded %T", decoded)
	}
}

// TestBdxStatusReportParityMatterJS: the StatusReport bytes of
// BdxStatusMessage.encode, both ways.
func TestBdxStatusReportParityMatterJS(t *testing.T) {
	t.Parallel()
	for _, fx := range loadFixtures(t).StatusReports {
		want, _ := hex.DecodeString(fx.BytesHex)
		if got := bdx.EncodeStatusReport(fx.GeneralStatus, bdx.StatusCode(fx.ProtocolStatus)); !bytes.Equal(got, want) {
			t.Fatalf("status %d/%d = %x, matter.js %x", fx.GeneralStatus, fx.ProtocolStatus, got, want)
		}
		sr, err := bdx.DecodeStatusReport(want)
		if err != nil || sr.GeneralStatus != fx.GeneralStatus || sr.ProtocolStatus != bdx.StatusCode(fx.ProtocolStatus) || sr.ProtocolID != bdx.ProtocolID {
			t.Fatalf("decode %x = %+v, %v", want, sr, err)
		}
	}
}

// TestBdxRefusedPayloadsParityMatterJS: a payload matter.js's decoder
// refuses is refused here with the same BdxStatusCode
// (BdxInitMessagesSchema.ts:185-210, BdxAcceptMessagesSchema.ts:82-98).
func TestBdxRefusedPayloadsParityMatterJS(t *testing.T) {
	t.Parallel()
	for _, fx := range loadFixtures(t).Refused {
		payload, _ := hex.DecodeString(fx.BytesHex)
		_, err := bdx.Decode(bdx.MessageType(fx.Kind), payload)
		var be *bdx.Error
		if !errors.As(err, &be) || be.Code != bdx.StatusCode(fx.Code) {
			t.Fatalf("%s: err = %v, want BDX error code %d", fx.Label, err, fx.Code)
		}
	}
}

// TestOtaImageParityMatterJS: an image matter.js's OtaImageWriter wrote
// reads to the header matter.js decodes, validates, extracts with a matching
// digest, and Create writes the same bytes.
func TestOtaImageParityMatterJS(t *testing.T) {
	t.Parallel()
	for _, fx := range loadFixtures(t).Images {
		t.Run(fx.Label, func(t *testing.T) {
			t.Parallel()
			image, _ := hex.DecodeString(fx.ImageHex)
			want := otaimage.Header{
				VendorID: fx.Header.VendorID, ProductID: fx.Header.ProductID,
				SoftwareVersion: fx.Header.SoftwareVersion, SoftwareVersionString: fx.Header.SoftwareVersionString,
				PayloadSize: fx.Header.PayloadSize, MinApplicableSoftwareVersion: fx.Header.MinApplicableSoftwareVersion,
				MaxApplicableSoftwareVersion: fx.Header.MaxApplicableSoftwareVersion, ReleaseNotesURL: fx.Header.ReleaseNotesURL,
				ImageDigestType: fx.Header.ImageDigestType, ImageDigest: fx.Header.ImageDigest.bytes(t),
			}
			h, err := otaimage.ValidateFile(bytes.NewReader(image), otaimage.FileOptions{})
			if err != nil {
				t.Fatal(err)
			}
			if !headersEqual(h, want) {
				t.Fatalf("header %+v, matter.js %+v", h, want)
			}
			var payload bytes.Buffer
			total := uint64(len(image))
			if _, err := otaimage.ExtractPayload(bytes.NewReader(image), &payload, &total); err != nil {
				t.Fatal(err)
			}
			if uint64(payload.Len()) != want.PayloadSize {
				t.Fatalf("payload %d bytes, want %d", payload.Len(), want.PayloadSize)
			}
			created, err := otaimage.Create(otaimage.CreateOptions{
				VendorID: want.VendorID, ProductID: want.ProductID, SoftwareVersion: want.SoftwareVersion,
				SoftwareVersionString: want.SoftwareVersionString, MinApplicableSoftwareVersion: want.MinApplicableSoftwareVersion,
				MaxApplicableSoftwareVersion: want.MaxApplicableSoftwareVersion, ReleaseNotesURL: want.ReleaseNotesURL,
				Payload: payload.Bytes(), ImageDigestType: want.ImageDigestType,
			})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(created, image) {
				t.Fatalf("Create differs from OtaImageWriter.create:\n got %x\nwant %x", created[:64], image[:64])
			}
		})
	}
}

func headersEqual(a, b otaimage.Header) bool {
	u32 := func(x, y *uint32) bool { return (x == nil && y == nil) || (x != nil && y != nil && *x == *y) }
	str := func(x, y *string) bool { return (x == nil && y == nil) || (x != nil && y != nil && *x == *y) }
	return a.VendorID == b.VendorID && a.ProductID == b.ProductID && a.SoftwareVersion == b.SoftwareVersion &&
		a.SoftwareVersionString == b.SoftwareVersionString && a.PayloadSize == b.PayloadSize &&
		u32(a.MinApplicableSoftwareVersion, b.MinApplicableSoftwareVersion) &&
		u32(a.MaxApplicableSoftwareVersion, b.MaxApplicableSoftwareVersion) &&
		str(a.ReleaseNotesURL, b.ReleaseNotesURL) && a.ImageDigestType == b.ImageDigestType &&
		bytes.Equal(a.ImageDigest, b.ImageDigest)
}
